    overflow-x: hidden;
}

ul {
    list-style: none;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--primary-color);
    color: #000;
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Header */
.main-header {
    background-color: rgba(10, 10, 10, 0.8);
    backdrop-filter: blur(10px);
    position: sticky;
    top: 0;
    z-index: 1000;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    height: 80px;
    display: flex;
    align-items: center;
}

.main-header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
}

.logo a {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.nav-menu ul {
    display: flex;
    gap: 2rem;
}

.nav-menu a:hover {
    color: var(--primary-color);
}

.header-actions {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.header-actions button {
    background: none;
    border: none;
    color: var(--text-primary);
    cursor: pointer;
    position: relative;
    display: flex;
    align-items: center;
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background-color: var(--primary-color);
    color: #000;
    font-size: 0.7rem;
    font-weight: bold;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

.menu-toggle {
    display: none;
}

/* Hero Section */
.hero {
    padding: 100px 0;
}

.hero-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.badge {
    color: var(--primary-color);
    text-transform: uppercase;
    font-size: 0.8rem;
    font-weight: bold;
    letter-spacing: 1px;
    display: block;
    margin-bottom: 1rem;
}

.hero h1 {
    font-size: 4rem;
    line-height: 1.1;
    margin-bottom: 1.5rem;
}

.hero p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
    max-width: 500px;
}

.btn {
    display: inline-block;
    padding: 1rem 2rem;
    border-radius: 4px;
    font-weight: 600;
    cursor: pointer;
    border: none;
    transition: var(--transition);
}

.btn-primary {
    background-color: var(--primary-color);
    color: #000;
}

.btn-primary:hover {
    background-color: #a370f0;
    transform: translateY(-2px);
}

.btn-outline {
    background-color: transparent;
    border: 2px solid var(--text-primary);
    color: var(--text-primary);
}

.btn-outline:hover {
    background-color: var(--text-primary);
    color: #000;
}

.placeholder-img {
    background: linear-gradient(45deg, #1a1a1a, #2a2a2a);
    width: 100%;
    aspect-ratio: 1;
    border-radius: 8px;
}

/* Products Section */
.products {
    padding: 80px 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 3rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--surface-color);
    border-radius: 12px;
    padding: 1.5rem;
    transition: var(--transition);
    border: 1px solid transparent;
}

.product-card:hover {
    border-color: rgba(255, 255, 255, 0.1);
    transform: translateY(-5px);
}

.product-img-wrapper {
    position: relative;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.add-to-cart {
    position: absolute;
    bottom: -50px;
    left: 0;
    width: 100%;
    padding: 0.8rem;
    background: var(--primary-color);
    color: #000;
    border: none;
    font-weight: bold;
    transition: var(--transition);
    cursor: pointer;
}

.product-card:hover .add-to-cart {
    bottom: 0;
}

.product-info h3 {
    margin-bottom: 0.5rem;
}

.price {
    color: var(--secondary-color);
    font-weight: bold;
}

/* Deals Section */
.deals {
    padding: 80px 0;
}

.deals-card {
    background: linear-gradient(to right, #1a1a1a, #0a0a0a);
    padding: 4rem;
    border-radius: 20px;
    border: 1px solid rgba(255, 255, 255, 0.05);
    text-align: center;
}

.deals-content h2 {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.timer {
    font-family: monospace;
    font-size: 2rem;
    margin: 2rem 0;
    color: var(--primary-color);
}

/* Footer */
.main-footer {
    padding: 80px 0 40px;
    background-color: #050505;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand h3 {
    margin-bottom: 1.5rem;
    letter-spacing: 2px;
}

.footer-brand p {
    color: var(--text-secondary);
}

.footer-links h4 {
    margin-bottom: 1.5rem;
}

.footer-links ul li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    color: var(--text-secondary);
}

.footer-links a:hover {
    color: var(--primary-color);
}

.footer-newsletter h4 {
    margin-bottom: 1rem;
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
    margin-top: 1.5rem;
}

.newsletter-form input {
    flex: 1;
    background-color: var(--surface-color);
    border: 1px solid rgba(255, 255, 255, 0.1);
    padding: 0.8rem;
    border-radius: 4px;
    color: #fff;
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background: var(--surface-color);
